 * ordering check reads, the ask the started run claims, and the instructions it reads —
 * so a caller that posted one shape and dispatched with another would leave a thread
 * that disagrees with itself. `dispatchPostMergeAgent` and
 * `dispatchUpdateConflictAgent` predate this and are left as they are; they are not
 * wrong, and rewriting a working path to share five lines is not worth the risk.
 */
function dispatchDirective(
  repo: string,
  number: number,
  agent: string,
  request: { context: string; directive: string; notify?: string },
): DispatchOutcome {
  const body = `${LLM_CONTEXT_TAG.write("include")}\n${DISPATCH_TAG.write(agent)}\n\n${request.directive}`;
  const markerCommentId = commentOnWithId(repo, number, body);
  if (markerCommentId === null) {
    log(`${request.context}: could not post the directive on #${number}, so ${agent} was not started`);
    return "failed";
  }
  return dispatchRunner({
    context: request.context,
    agent,
    type: "issue",
    number,
    notify: request.notify ?? "",
    repo,
    markerCommentId,
    log,
  });
}
